style.css:
@-moz-document domain("roblox.com") {
/* ==========================================================================
   ☁️? CLOUD AURORA — ROBLOX ?☁️
   Pastel Aurora • Frosted Glass • Pearl Lavender

   Designed, styled & maintained by:
   ?՞. .՞?Cloud Aurora?՞. .՞? / ☁️Cloud Aurora☁️
   @Aurora_Cloud

   This is my Cloud Aurora. A complete visual redesign for Roblox built around
   soft pastel auroras, pearl glass materials, lavender tones and
   carefully layered transparency.

   Every major surface has been individually styled to preserve Roblox's
   native functionality while transforming its visual identity into the
   Cloud Aurora aesthetic.

   Please preserve the original creator credits when modifying,
   redistributing or building upon this style.

   Stylish targets:
   https://www.roblox.com/
   https://roblox.com/
   ========================================================================== */
  
/* ##########################################################################
   PART I — DESIGN FOUNDATION
   Core tokens, wallpaper layer, native resets, typography and global navigation.
   General systems come before page-specific styling so later sections can specialize them.
   ########################################################################## */

/* ==========================================================================
   01. CLOUD AURORA DESIGN TOKENS
   Master palette, gradients, glass materials, shadows, radii and component variables.
   ========================================================================== */

:root {
    --ca-white: #fff8fd;
    --ca-white-soft: #faeefa;
    --ca-pink: #f3b6d2;
    --ca-pink-soft: #ffd1e4;
    --ca-pink-deep: #da8fba;
    --ca-lavender: #cfb3f3;
    --ca-lavender-soft: #e5d2fa;
    --ca-lavender-deep: #a979d2;
    --ca-purple: #9567c3;
    --ca-blue: #b7ddf8;
    --ca-blue-soft: #d7edff;
    --ca-aqua: #aeedea;
    --ca-aqua-soft: #d1f7f2;
    --ca-peach: #ffd0c8;
    --ca-peach-soft: #ffe3dc;
    --ca-text: #463451;
    --ca-text-soft: #776283;
    --ca-text-muted: #a08da8;
    --ca-text-on-strong: #ffffff;
    --ca-glass: rgba(240, 220, 248, 0.62);
    --ca-glass-heavy: rgba(241, 224, 248, 0.88);
    --ca-glass-hover: rgba(223, 193, 243, 0.72);
    --ca-border: rgba(255, 255, 255, 0.58);
    --ca-border-strong: rgba(255, 255, 255, 0.70);
    --ca-border-purple: rgba(177, 137, 211, 0.28);
    --ca-shadow: 0 8px 30px rgba(102, 71, 128, 0.10);
    --ca-shadow-heavy: 0 18px 48px rgba(102, 67, 130, 0.18);
    --ca-glow: 0 0 25px rgba(186, 144, 220, 0.18);
    --ca-radius-sm: 10px;
    --ca-radius: 12px;
    --ca-radius-lg: 17px;
    --ca-radius-xl: 19px;
    --ca-radius-pill: 999px;
    --ca-aurora-gradient: linear-gradient(
            110deg,
            #d4b6f1 0%,
            #e7b9ee 22%,
            #f4bbd5 44%,
            #c9e4f7 70%,
            #bdede5 100%
        );
    --ca-aurora-gradient-soft: linear-gradient(
            110deg,
            rgba(216, 188, 244, 0.68) 0%,
            rgba(239, 194, 236, 0.63) 27%,
            rgba(250, 196, 220, 0.60) 49%,
            rgba(196, 228, 247, 0.62) 72%,
            rgba(190, 238, 231, 0.60) 100%
        );
    --ca-aurora-gradient-hover: linear-gradient(
            110deg,
            #c7a1eb 0%,
            #e1a9e8 25%,
            #eea4c9 48%,
            #abddf4 73%,
            #a7e7df 100%
        );
    --ca-aurora-gradient-light: linear-gradient(
            110deg,
            rgba(227, 207, 248, 0.56),
            rgba(248, 215, 235, 0.54),
            rgba(211, 236, 250, 0.52),
            rgba(207, 244, 237, 0.50)
        );
    --ca-header-gradient: linear-gradient(
            105deg,
            rgba(215, 238, 250, 0.76) 0%,
            rgba(230, 207, 248, 0.78) 31%,
            rgba(247, 211, 232, 0.76) 64%,
            rgba(218, 239, 244, 0.72) 100%
        );
    --ca-sidebar-surface: linear-gradient(
            165deg,
            rgba(241, 218, 250, 0.86) 0%,
            rgba(251, 224, 241, 0.85) 45%,
            rgba(220, 238, 249, 0.84) 100%
        );
    --ca-side-text: #594463;
    --ca-side-text-strong: #46304f;
    --ca-side-icon: #72547f;
    --ca-side-border: rgba(255, 255, 255, 0.62);
    --ca-side-border-hover: rgba(255, 255, 255, 0.82);
    --ca-side-aurora-1: linear-gradient(
            105deg,
            rgba(196, 156, 235, 0.72) 0%,
            rgba(223, 171, 231, 0.70) 23%,
            rgba(244, 186, 214, 0.68) 48%,
            rgba(183, 219, 240, 0.67) 74%,
            rgba(177, 231, 224, 0.66) 100%
        );
    --ca-side-aurora-2: linear-gradient(
            255deg,
            rgba(192, 154, 234, 0.70) 0%,
            rgba(225, 174, 232, 0.68) 28%,
            rgba(245, 188, 215, 0.67) 51%,
            rgba(181, 220, 241, 0.68) 78%,
            rgba(174, 232, 224, 0.67) 100%
        );
    --ca-side-pearl: linear-gradient(
            180deg,
            rgba(255, 255, 255, 0.54) 0%,
            rgba(255, 255, 255, 0.22) 25%,
            rgba(255, 255, 255, 0.06) 52%,
            rgba(255, 255, 255, 0.16) 100%
        );
    --ca-side-inner-glow: radial-gradient(
            ellipse at 50% -25%,
            rgba(255, 255, 255, 0.68),
            transparent 58%
        );
    --ca-panel-gradient: linear-gradient(
            145deg,
            rgba(240, 224, 250, 0.94),
            rgba(250, 224, 238, 0.92),
            rgba(219, 238, 248, 0.92)
        );
    --ca-description-gradient: linear-gradient(
            120deg,
            rgba(232, 211, 248, 0.63),
            rgba(248, 215, 234, 0.58),
            rgba(212, 236, 247, 0.58)
        );
    --ca-player-progress: linear-gradient(
            90deg,
            #eb94c0 0%,
            #b47ddd 52%,
            #83d8de 100%
        );
    --ca-wallpaper-position: center center;
    --ca-wallpaper-size: cover;
    --ca-feed-header-glass: linear-gradient(
            105deg,
            rgba(204, 231, 247, 0.90) 0%,
            rgba(220, 211, 246, 0.91) 24%,
            rgba(242, 208, 234, 0.90) 50%,
            rgba(215, 225, 248, 0.90) 72%,
            rgba(199, 238, 237, 0.89) 100%
        );
    --ca-chip-aurora-1: linear-gradient(
            105deg,
            rgba(198, 160, 235, 0.68) 0%,
            rgba(225, 176, 232, 0.66) 27%,
            rgba(244, 192, 216, 0.64) 50%,
            rgba(187, 221, 240, 0.64) 75%,
            rgba(181, 232, 225, 0.63) 100%
        );
    --ca-chip-aurora-2: linear-gradient(
            255deg,
            rgba(194, 158, 234, 0.67) 0%,
            rgba(226, 178, 232, 0.65) 30%,
            rgba(245, 193, 216, 0.64) 52%,
            rgba(184, 222, 241, 0.65) 78%,
            rgba(177, 233, 225, 0.64) 100%
        );
    --ca-chip-pearl: linear-gradient(
            180deg,
            rgba(255, 255, 255, 0.55) 0%,
            rgba(255, 255, 255, 0.22) 28%,
            rgba(255, 255, 255, 0.05) 56%,
            rgba(255, 255, 255, 0.12) 100%
        );
    --ca-chip-selected: linear-gradient(
            105deg,
            #c89aeb 0%,
            #e5a8e5 25%,
            #f2afd0 48%,
            #aedcf0 74%,
            #abe7df 100%
        );
    /* Component tokens extracted from final declarations, not new palettes. */
    --ca-wallpaper-veil: linear-gradient(115deg, rgba(255,255,255,.05) 0%, rgba(232,220,250,.04) 38%, rgba(255,219,235,.04) 67%, rgba(205,239,244,.04) 100%);
    --ca-wallpaper-haze: linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(249,239,250,.03) 55%, rgba(249,232,244,.08) 100%);
    --ca-metadata-white: rgba(255,255,255,.94);
    --ca-title-shadow: -1px -1px 0 rgba(91,57,119,.84), 1px -1px 0 rgba(91,57,119,.84), -1px 1px 0 rgba(91,57,119,.84), 1px 1px 0 rgba(91,57,119,.84), 0 1px 2px rgba(73,44,96,.58), 0 0 5px rgba(149,103,195,.34);
    --ca-metadata-shadow: -1px 0 0 rgba(100,64,130,.68), 1px 0 0 rgba(100,64,130,.68), 0 -1px 0 rgba(100,64,130,.68), 0 1px 0 rgba(100,64,130,.68), 0 1px 2px rgba(73,44,96,.44);
    --ca-pearl-text-shadow: 0 1px 1px rgba(255,255,255,.28);
    --ca-blur-header: blur(28px) saturate(145%) brightness(1.04);
    --ca-blur-panel: blur(28px) saturate(145%);
    --ca-header-shadow: inset 0 1px 0 rgba(255,255,255,.54), inset 0 -1px 0 rgba(190,160,215,.10), 0 5px 20px rgba(105,75,130,.07);
    --ca-search-surface: linear-gradient(100deg, rgba(255,246,253,.72), rgba(237,221,250,.67), rgba(222,239,251,.65));
    --ca-search-border: rgba(180,132,216,.28);
    --ca-search-focus: linear-gradient(100deg, rgba(255,247,253,.84), rgba(239,223,251,.80), rgba(224,241,252,.78));
    --ca-search-shadow: inset 0 1px rgba(255,255,255,.80), 0 5px 20px rgba(137,91,166,.09);
    --ca-search-focus-shadow: 0 0 0 4px rgba(193,141,230,.12), 0 0 26px rgba(227,157,210,.16);
    --ca-card-surface: linear-gradient(145deg, rgba(255,255,255,.18), rgba(233,208,247,.18), rgba(210,236,248,.13));
    --ca-card-hover: linear-gradient(145deg, rgba(238,217,251,.44), rgba(250,210,231,.40), rgba(203,237,244,.38));
    --ca-card-hover-shadow: inset 0 0 0 1px rgba(255,255,255,.42), 0 15px 36px rgba(123,85,151,.11), 0 0 26px rgba(193,144,232,.10);
    --ca-button-shadow: inset 0 1px rgba(255,255,255,.44), 0 5px 14px rgba(111,77,136,.08);
    --ca-button-hover-shadow: 0 7px 20px rgba(140,90,168,.16), 0 0 16px rgba(218,165,227,.12);
    --ca-chip-shadow: inset 0 1px 0 rgba(255,255,255,.70), inset 0 -1px 0 rgba(255,255,255,.16), 0 3px 9px rgba(100,70,120,.06);
    --ca-side-reflection: linear-gradient(115deg, rgba(255,255,255,.154) 0%, transparent 25%, rgba(255,255,255,.056) 45%, rgba(255,255,255,.196) 67%, transparent 88%);
    --ca-side-reflection-hover: linear-gradient(115deg, rgba(255,255,255,.2024) 0%, transparent 25%, rgba(255,255,255,.0736) 45%, rgba(255,255,255,.2576) 67%, transparent 88%);
    --ca-side-shadow: inset 0 1px 0 rgba(255,255,255,.64), inset 0 -1px 0 rgba(255,255,255,.18), 0 4px 10px rgba(104,72,122,.07);
    --ca-side-hover-shadow: inset 0 1px 0 rgba(255,255,255,.86), inset 0 -1px 0 rgba(255,255,255,.24), 0 8px 18px rgba(108,70,132,.13), 0 0 15px rgba(211,173,232,.11);
    --ca-side-active-shadow: inset 0 1px 0 rgba(255,255,255,.94), inset 0 -1px 0 rgba(255,255,255,.24), 0 8px 20px rgba(124,76,151,.18), 0 0 18px rgba(209,159,228,.15);
    /* Last effective description/comments overrides in the frozen master. */
    --ca-description-final: rgba(143,138,186,.80);
    --ca-description-border: rgba(224,218,255,.56);
    --ca-description-shadow: inset 0 1px 0 rgba(255,255,255,.26), 0 7px 18px rgba(86,76,132,.13);
    --ca-description-text-shadow: -1px -1px 0 rgba(91,57,119,.78), 1px -1px 0 rgba(91,57,119,.78), -1px 1px 0 rgba(91,57,119,.78), 1px 1px 0 rgba(91,57,119,.78), 0 1px 2px rgba(73,44,96,.42);
    --ca-comments-final: rgba(143,138,186,.76);
    --ca-comments-border: rgba(220,214,252,.52);
    --ca-comments-shadow: inset 0 1px 0 rgba(255,255,255,.22), 0 10px 24px rgba(82,72,126,.12);
   --ca-wallpaper: url("data:image/webp;base64,");
}
  
/* ==========================================================================
   02. WALLPAPER + ROOT PAGE
   Fixed wallpaper composition with the original veil/haze layers.
   ========================================================================== */

html {
    background-color: #dedcf3 !important;
    background-image: var(--ca-wallpaper-haze), var(--ca-wallpaper-veil), var(--ca-wallpaper) !important;
    background-position: center center !important;
    background-size: cover !important;
    background-repeat: no-repeat !important;
    background-attachment: fixed !important;
}

/* ==========================================================================
   03. ROBLOX NATIVE BACKGROUND RESET
   Clears explicit Roblox page shells without globally resetting dark/light-theme descendants.
   ========================================================================== */

body#rbx-body,
#wrap,
#container-main,
#content,
.games-page-container,
.games-list-container,
#game-detail-page .game-main-content,
#game-detail-page .rbx-tab-content {
    background: transparent !important;
}

/* ==========================================================================
   04. TYPOGRAPHY + CONTRAST
   High-contrast titles and metadata over the wallpaper; pearl controls keep plum text.
   ========================================================================== */

.games-page-container h1,
.games-page-container .sort-header,
.games-page-container .sort-header a,
.game-card-container .game-card-name,
#game-detail-page .game-name,
#game-detail-page .container-header h2 {
    color: var(--ca-text-on-strong) !important;
    text-shadow: var(--ca-title-shadow) !important;
}
.game-card-container .vote-percentage-label,
.game-card-container .playing-counts-label,
#game-detail-page .game-creator .text-label,
#game-detail-page .game-creator .text-name,
#game-detail-page #game-age-recommendation-container {
    color: var(--ca-metadata-white) !important;
    text-shadow: var(--ca-metadata-shadow) !important;
}

/* ==========================================================================
   05. TOP NAVIGATION
   Frosted Aurora header surface and navigation hover material.
   ========================================================================== */

#header.rbx-header {
    background: var(--ca-feed-header-glass) !important;
    border-bottom: 1px solid var(--ca-border) !important;
    box-shadow: var(--ca-header-shadow) !important;
    -webkit-backdrop-filter: var(--ca-blur-header);
    backdrop-filter: var(--ca-blur-header);
}
#header .nav-menu-title {
    color: var(--ca-text) !important;
    text-shadow: var(--ca-pearl-text-shadow) !important;
    border-radius: var(--ca-radius-sm) !important;
}
#header .nav-menu-title:hover {
    background: var(--ca-aurora-gradient-light) !important;
}

/* ==========================================================================
   06. SEARCH — CORE + FINAL SURFACE
   Base search styling followed immediately by the later live-verified input surface.
   ========================================================================== */

#header .navbar-search > .input-group {
    background: var(--ca-search-surface) !important;
    border-radius: var(--ca-radius-pill) !important;
    box-shadow: var(--ca-search-shadow) !important;
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
}
#header #navbar-search-input {
    background: transparent !important;
    border: 1px solid var(--ca-search-border) !important;
    border-radius: var(--ca-radius-pill) !important;
    color: var(--ca-text) !important;
    caret-color: var(--ca-purple);
    text-shadow: none !important;
}
#header #navbar-search-input::placeholder {
    color: var(--ca-text-soft) !important;
    opacity: 1;
}

#header #navbar-search-input:focus {
    outline: 2px solid var(--ca-purple) !important;
    outline-offset: 2px;
}
#header .navbar-search .input-addon-btn {
    background: var(--ca-aurora-gradient) !important;
    border: 1px solid var(--ca-border) !important;
    border-radius: var(--ca-radius-pill) !important;
    color: var(--ca-text) !important;
}
#header .navbar-search .input-addon-btn:hover {
    background: var(--ca-aurora-gradient-hover) !important;
}

#rbx-body #header .navbar-search,
#rbx-body #header .navbar-search > .input-group,
#rbx-body #header .navbar-search .input-group form,
#rbx-body #header .navbar-search .form-has-feedback,
#rbx-body #header .navbar-search .input-group-btn {
    background: transparent !important;
    border-color: transparent !important;
    box-shadow: none !important;
}
#rbx-body #header #navbar-search-input {
    background: var(--ca-search-surface) !important;
    border: 1px solid var(--ca-border-strong) !important;
    border-radius: var(--ca-radius-pill) !important;
    box-shadow: var(--ca-search-shadow) !important;
    color: var(--ca-text) !important;
    -webkit-text-fill-color: var(--ca-text) !important;
    -webkit-backdrop-filter: blur(18px);
    backdrop-filter: blur(18px);
    color-scheme: light;
}
#rbx-body #header #navbar-search-input::placeholder {
    color: var(--ca-text-soft) !important;
    -webkit-text-fill-color: var(--ca-text-soft) !important;
    opacity: 1 !important;
}
#rbx-body #header #navbar-search-input:focus {
    background: var(--ca-search-focus) !important;
    border-color: var(--ca-lavender-deep) !important;
    box-shadow: var(--ca-search-focus-shadow) !important;
}
#rbx-body #header .navbar-search .input-addon-btn {
    background: var(--ca-aurora-gradient) !important;
    border: 1px solid var(--ca-border-strong) !important;
    box-shadow: var(--ca-button-shadow) !important;
}
#rbx-body #header .navbar-search .input-addon-btn:hover {
    background: var(--ca-aurora-gradient-hover) !important;
}
/* Only the native monochrome search sprite; never a media filter. */
#rbx-body #header .navbar-search .icon-common-search-sm {
    filter: brightness(.45) sepia(.25) !important;
    opacity: 1 !important;
}

/* ==========================================================================
   07. LEFT SIDEBAR — MODERN PEARL MATERIAL
   Modern sidebar surface, link materials, semantic states, text and icon handling.
   ========================================================================== */

#left-navigation-container .left-nav {
    background: var(--ca-sidebar-surface) !important;
    border-right: 1px solid var(--ca-border) !important;
    -webkit-backdrop-filter: blur(28px) saturate(135%);
    backdrop-filter: blur(28px) saturate(135%);
}
#left-navigation-container .left-nav > div,
#left-navigation-container .left-nav > div > div,
#left-navigation-container .left-nav > div > div > div {
    background-color: transparent !important;
}
#left-navigation-container .left-nav nav a,
#left-navigation-container .left-nav nav button[type="button"],
#left-navigation-container .left-nav a[href="/users/profile"],
#left-navigation-container .left-nav a[href="/users"] {
    --ca-nav-material: var(--ca-side-aurora-1);
    --ca-nav-ink: var(--ca-side-text);
    background: var(--ca-side-reflection), var(--ca-side-pearl), var(--ca-side-inner-glow), var(--ca-nav-material) !important;
    color: var(--ca-nav-ink) !important;
    border-radius: 11px !important;
    box-shadow: inset 0 0 0 1px var(--ca-side-border), var(--ca-side-shadow) !important;
    -webkit-backdrop-filter: blur(13px) saturate(125%);
    backdrop-filter: blur(13px) saturate(125%);
    text-shadow: var(--ca-pearl-text-shadow) !important;
    transition: box-shadow .20s ease, background .20s ease;
}
/* Material variation by known destinations, independent of list order. */
#left-navigation-container .left-nav nav a[href*="/plus"],
#left-navigation-container .left-nav nav a[href="/users"] {
    --ca-nav-material: var(--ca-side-aurora-2);
}
#left-navigation-container .left-nav nav a:hover,
#left-navigation-container .left-nav nav button[type="button"]:hover,
#left-navigation-container .left-nav a[href="/users/profile"]:hover,
#left-navigation-container .left-nav a[href="/users"]:hover {
    --ca-nav-ink: var(--ca-side-text-strong);
    background: var(--ca-side-reflection-hover), var(--ca-side-pearl), var(--ca-side-inner-glow), var(--ca-nav-material) !important;
    box-shadow: inset 0 0 0 1px var(--ca-side-border-hover), var(--ca-side-hover-shadow) !important;
}
#left-navigation-container .left-nav nav a[aria-current="page"],
#left-navigation-container .left-nav nav a[aria-selected="true"],
#left-navigation-container .left-nav nav a[aria-pressed="true"],
#left-navigation-container .left-nav nav button[type="button"][aria-current="page"],
#left-navigation-container .left-nav nav button[type="button"][aria-selected="true"],
#left-navigation-container .left-nav nav button[type="button"][aria-pressed="true"],
#left-navigation-container .left-nav a[href="/users/profile"][aria-current="page"],
#left-navigation-container .left-nav a[href="/users/profile"][aria-selected="true"],
#left-navigation-container .left-nav a[href="/users/profile"][aria-pressed="true"],
#left-navigation-container .left-nav a[href="/users"][aria-current="page"],
#left-navigation-container .left-nav a[href="/users"][aria-selected="true"],
#left-navigation-container .left-nav a[href="/users"][aria-pressed="true"] {
    --ca-nav-ink: var(--ca-side-text-strong);
    background: var(--ca-side-pearl), var(--ca-side-inner-glow), var(--ca-chip-selected) !important;
    box-shadow: inset 0 0 0 1px rgba(255,255,255,.96), var(--ca-side-active-shadow) !important;
}
#left-navigation-container .left-nav nav a .text-truncate-end,
#left-navigation-container .left-nav nav a .nav-item-text,
#left-navigation-container .left-nav nav a span:not([class]),
#left-navigation-container .left-nav nav button[type="button"] .text-truncate-end,
#left-navigation-container .left-nav nav button[type="button"] .nav-item-text,
#left-navigation-container .left-nav nav button[type="button"] span:not([class]),
#left-navigation-container .left-nav a[href="/users/profile"] .text-truncate-end,
#left-navigation-container .left-nav a[href="/users/profile"] .nav-item-text,
#left-navigation-container .left-nav a[href="/users/profile"] span:not([class]),
#left-navigation-container .left-nav a[href="/users"] .text-truncate-end,
#left-navigation-container .left-nav a[href="/users"] .nav-item-text,
#left-navigation-container .left-nav a[href="/users"] span:not([class]) {
    color: var(--ca-nav-ink) !important;
    text-shadow: var(--ca-pearl-text-shadow) !important;
}
#left-navigation-container .left-nav nav a svg,
#left-navigation-container .left-nav nav a .icon,
#left-navigation-container .left-nav nav a .nav-item-icon,
#left-navigation-container .left-nav nav button svg,
#left-navigation-container .left-nav nav button .icon,
#left-navigation-container .left-nav nav button .nav-item-icon {
    color: var(--ca-side-icon) !important;
}
/* Only the specific decorative overlay reported in Source B. */
#left-navigation-container .left-nav nav a > div[role="presentation"] {
    background-color: transparent !important;
}

/* ##########################################################################
   PART II — SHARED COMPONENT SYSTEMS
   Reusable Roblox components: cards, filters, buttons, dropdowns and interaction states.
   Page-specific modules appear only after these shared materials are established.
   ########################################################################## */

/* ==========================================================================
   08. EXPERIENCE CARDS
   Aurora card material, hover lift and thumbnail radii without changing native dimensions.
   ========================================================================== */

.game-card-container:not(.game-card-loading) {
    background: var(--ca-card-surface) !important;
    border-radius: var(--ca-radius-xl) !important;
    box-shadow: inset 0 0 0 1px transparent;
    transition: transform .22s ease, box-shadow .22s ease, background .22s ease;
}

    .game-card-container:not(.game-card-loading):hover {
        background: var(--ca-card-hover) !important;
